);
if
(month_name ==
"Aug"
)
return
(
8
);
if
(month_name ==
"Sep"
)
return
(
9
);
if
(month_name ==
"Oct"
)
return
(
10
);
if
(month_name ==
"Nov"
)
return
(
11
);
if
(month_name ==
"Dec"
)
return
(
12
);
//--- unknown month name
