//| Implements the currency filter primitives: extracts the base and |
//| quote currencies from a symbol name after stripping any broker   |
//| suffix, and matches an event currency against either side.       |
//+------------------------------------------------------------------+
class
CCurrencyExtractor
  {
private
:
string
StripSuffix(
const
string
symbol)
const
;
public
:
                     CCurrencyExtractor(
void
);
                    ~CCurrencyExtractor(
void
);
string
GetBaseCurrency(
const
string
symbol)
const
;
string
